CREATE TABLE pacotes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome_arquivo VARCHAR(255) NOT NULL, sha256 VARCHAR(64) NOT NULL UNIQUE, configuracao_sha256 VARCHAR(64) NOT NULL, criado_em TIMESTAMP(6) WITH TIME ZONE NOT NULL);
CREATE TABLE pacote_documentos (pacote_id BIGINT NOT NULL REFERENCES pacotes(id), documento_id BIGINT NOT NULL REFERENCES documentos(id), PRIMARY KEY(pacote_id, documento_id));
CREATE TABLE anexos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pacote_id BIGINT NOT NULL REFERENCES pacotes(id), nome_arquivo VARCHAR(255) NOT NULL, finalidade VARCHAR(30) NOT NULL CHECK (finalidade IN ('VIAGEM','FATURA')), caminho VARCHAR(255) NOT NULL, sha256 VARCHAR(64) NOT NULL, token VARCHAR(36) NOT NULL UNIQUE, numero_armazenamento VARCHAR(9) NOT NULL, arquivado_em TIMESTAMP(6) WITH TIME ZONE);
CREATE TABLE anexo_viagens (anexo_id BIGINT NOT NULL REFERENCES anexos(id), viagem_id BIGINT NOT NULL REFERENCES viagens(id), PRIMARY KEY(anexo_id, viagem_id));
CREATE INDEX idx_anexo_viagens_viagem ON anexo_viagens(viagem_id);
CREATE INDEX idx_anexos_pacote ON anexos(pacote_id);
